        [ex("Título: Happy Birthday. Dibujo: una torta con velas y globos. Escribe una predicción en inglés con estas palabras: cake, birthday.", "Por ejemplo: It is a birthday cake.", "La respuesta debe usar cake y birthday según las pistas del dibujo."),
         ex("Título: Summer. Texto: The sun is hot. ¿Qué dibujo NO encaja con el título ni con el texto: un sol, un helado o la nieve?", "la nieve", "Summer es verano y el sol está caliente, así que la nieve no encaja.")],
