        [ex("¿Por qué puedes entender family aunque no sepas inglés?", "Porque se parece a familia", "Se escriben casi igual y significan lo mismo."),
         ex("¿Qué haces primero si no entiendes todo un texto?", "Busco las palabras que conozco", "Con esas palabras se entienden otras."),
         ex("¿Cuál de estas palabras es parecida al español: music o hat?", "music", "Music se parece a música.")],
        [ex("Lee: I like chocolate. ¿Qué palabra se parece al español y qué significa?", "chocolate; chocolate", "Se escribe igual y significa lo mismo."),
         ex("Lee: The doctor has a blue bag. ¿Qué dos palabras conoces? Elige entre doctor, blue, bag.", "doctor y blue", "Doctor es doctor y blue es azul; bag lo puedes aprender luego."),
         ex("Lee: My banana is yellow. Si yellow es amarillo, ¿qué color tiene la banana?", "Amarillo", "Se usa lo que sé: yellow es amarillo.")],
        [ex("Leo: The color of the cat is red. Me confundo con color. ¿Qué palabra parecida me ayuda y qué significa?", "color; color", "Color se escribe casi igual y se usa igual."),
         ex("Dos niños leen I eat a banana. Uno dice que se come una fruta. El otro dice que se pinta una pared. ¿Quién usa mejor lo que sabe?", "El primero", "Una banana es una fruta, no se pinta una pared.")],
        [ex("Lee: The animal is a big dog. Escribe en español qué entiendes usando las palabras conocidas.", "El animal es un perro grande", "Animal, big y dog dan el significado.") ,
         ex("Lee: My family likes music. Solo conoces family y music. ¿Sobre qué crees que habla la oración?", "Sobre la familia y la música", "Las dos palabras conocidas dan el tema.")],
