# ---------------------------------------------------------------- OA 09
register(
    OA9, 1,
    materials="Textos cortos escritos en este cuaderno y una hoja para dibujar o escribir.",
    use="Aprenderé a decir si lo que leí se parece a algo que me pasó. Sirve para entender mejor los textos y sentirlos cercanos.",
    prior=["Sé leer oraciones simples.", "Sé decir I like y I have."],
    explain=[
        "Cuando lees, puedes pensar en tu propia vida. Si el texto dice I have a dog y tú también tienes un perro, hiciste una conexión. Esa conexión se llama de texto a mí: el texto se parece a algo que te pasa.",
        "Para conectar, hazte una pregunta: ¿me pasó algo parecido? Puedes responder con la frase Me too (yo también). También puedes decir I have a dog too (yo también tengo un perro).",
        "No hay respuestas buenas o malas, porque cada persona vive cosas distintas. Lo importante es que expliques tu conexión con el texto. Nunca tienes que contar cosas privadas: basta con algo simple, como un animal, una comida o un juego.",
    ],
    vocab=[("connection", "conexión: algo que se parece a mi vida"), ("me too", "yo también"), ("I have", "yo tengo"), ("like", "gustar"), ("dog", "perro"), ("too", "también")],
    worked=[
        W("Conectar con una experiencia", "Texto: I have a dog. His name is Max. ¿Qué conexión puedes hacer si tienes un perro?",
          ["Leo el texto: la persona tiene un perro.", "Pienso en mi vida: yo también tengo un perro.", "Digo: Me too. I have a dog."],
          "Me too. I have a dog."),
        W("Conectar sin tener lo mismo", "El mismo texto. Si no tienes perro pero tienes un gato, ¿qué conexión haces?",
          ["Leo: la persona tiene un perro.", "Pienso en mi mascota: un gato.", "Digo: I have a cat."],
          "I have a cat. (Mi mascota es distinta, pero también tengo un animal)."),
    ],
    mistakes=[
        M("Decir que no hay conexión porque no tengo lo mismo.", "Se busca una igualdad exacta.", "Busca algo parecido: otra mascota, otra comida, otro juego."),
        M("Contar cosas muy privadas.", "No se piensa qué compartir.", "Elige algo simple y que te sientas cómodo compartiendo."),
    ],
    tiers=T(
        [ex("Texto: I like pizza. Si a ti también te gusta, ¿qué dices en inglés: Me too o I do not?", "Me too", "Me too significa yo también."),
         ex("¿Qué significa dog?", "Perro", "Dog es perro."),
         ex("Texto: I have a cat. Completa: I have a ___ too (si tienes un gato).", "cat", "Se repite la palabra del texto.")],
        [ex("¿Qué es una conexión entre el texto y mi vida?", "Algo del texto que se parece a mi vida", "Une lo que leo con lo que vivo."),
         ex("Si el texto habla de un perro y yo tengo un pez, ¿puedo conectar?", "Sí, con otra mascota", "Se puede conectar con algo parecido."),
         ex("¿Qué significa too en I like pizza too?", "También", "Too es también.")],
        [ex("Texto: I play with a ball. Escribe una conexión en español: ¿con qué juegas tú?", "Por ejemplo: Yo juego con una pelota", "Cualquier juego propio sirve si lo explicas."),
         ex("Texto: I eat an apple. ¿Qué conexión hace alguien a quien le gustan las manzanas? Elige: Me too o No.", "Me too", "Le gusta comer manzanas."),
         ex("Texto: I have a red bike. Si tienes una bicicleta, completa: I have a ___ too.", "bike", "Bike es bicicleta.")],
        [ex("Ana dice que no puede conectar con el texto I like music porque no toca guitarra. ¿Qué le dirías?", "Que puede conectar si le gusta escuchar música", "La conexión no tiene que ser idéntica."),
         ex("¿Por qué no hay respuestas buenas o malas al conectar?", "Porque cada persona vive cosas distintas", "Las experiencias de cada uno son propias.")],
        [ex("Texto: My family eats pizza on Friday (Friday = viernes). Escribe en español una conexión con tu familia y un día.", "Por ejemplo: Mi familia come pizza el sábado", "La respuesta usa la idea de familia y comida."),
         ex("Lee: I like dogs. Si a ti también te gustan los perros, completa la conexión en inglés: I like ___ too.", "dogs", "Se repite la palabra del texto: I like dogs too.")],
    ),
    context=[ex("En clase la profesora lee: I have a little brother. His name is Leo. Piensa en alguien de tu familia o en un amigo que sea pequeño. ¿Qué conexión puedes decir en español?", "Por ejemplo: Yo tengo un primo pequeño", "Brother es hermano. Se puede conectar con un hermano, un primo o un amigo; no hace falta tener hermanos.")],
    selfcheck=[ex("¿Cómo se dice yo también en inglés?", "Me too", "Es la forma corta."),
               ex("¿Se debe contar algo muy privado para conectar?", "No", "Basta con algo simple."),
               ex("Texto: I like red. ¿Qué dirías si el rojo es tu color favorito?", "Me too", "Compartes el gusto por el rojo.")],
    open_task=task("Lee estas tres oraciones: I have a cat. I like pizza. I play with a ball. Elige la que más se parezca a ti. Escribe en inglés Me too y dibuja lo que se parece a tu vida.",
                   "Elegí I like pizza. Escribí Me too. Dibujé una pizza con queso.",
                   ["elige una oración", "escribe Me too o una frase propia", "dibuja algo relacionado"], ["oración elegida", "dibujo"], ["no explicar la conexión", "copiar sin pensar en su vida"],
                   "Pide que cuente por qué eligió esa oración. Acepta cualquier conexión razonable."),
    reinforce="Cuéntale a un adulto una cosa que tengas o te guste igual que alguien de un cuento.",
    extend="Escribe dos oraciones en inglés con I like y I have sobre ti, con ayuda de un adulto.",
)

