register(
    OA9, 3,
    materials="Una escena breve escrita en este cuaderno. Se puede actuar con objetos de la casa. Necesitas un adulto o un amigo.",
    use="Aprenderé a actuar una escena corta con gestos y frases en inglés. Sirve para sentir la historia y mostrar cómo me siento al leerla.",
    prior=["Sé decir Hello y I am happy.", "Sé usar gestos para mostrar una emoción."],
    explain=[
        "Dramatizar es actuar un texto como si fuera una obra de teatro. Tú eres un personaje: dices sus frases y haces sus gestos. Con eso muestras que entendiste la escena.",
        "Para dramatizar, primero lee la escena y decide quién habla y qué siente cada personaje. Si el personaje está happy (contento), sonríes; si está sad (triste), bajas la cara. Los gestos ayudan a que se entienda.",
        "Habla con voz clara y despacio. Si olvidas una frase, mira el texto y sigue. No importa equivocarse: lo importante es participar y divertirse. Si te da vergüenza, puedes usar una marioneta o un peluche.",
    ],
    vocab=[("act", "actuar"), ("scene", "escena"), ("happy", "contento"), ("sad", "triste"), ("say", "decir"), ("character", "personaje")],
    worked=[
        W("Escoger el gesto", "Escena: Mia is sad. Her ball is lost. ¿Qué gesto haces como Mia?",
          ["Leo sad: triste.", "Pongo cara triste y bajo los hombros.", "Digo con voz baja: My ball!"],
          "Cara triste y voz baja."),
        W("Escoger la voz", "Escena: Tom is happy. He has a new bike. ¿Cómo suena su voz?",
          ["Leo happy: contento.", "Sonrío y levanto los brazos.", "Digo con voz fuerte y alegre: My new bike!"],
          "Voz alegre y sonrisa."),
    ],
    mistakes=[
        M("Actuar sin mirar cómo se siente el personaje.", "Se piensa solo en las palabras.", "Busca happy o sad en la escena y usa ese gesto."),
        M("Hablar tan bajo que nadie escucha.", "La vergüenza hace bajar la voz.", "Respira, habla despacio y más fuerte."),
    ],
    tiers=T(
        [ex("¿Qué significa happy?", "Contento", "Happy es contento."),
         ex("¿Qué cara pones si el personaje está sad?", "Triste", "Sad es triste."),
         ex("¿Qué significa act?", "Actuar", "Es hacer de personaje.")],
        [ex("¿Para qué sirve dramatizar?", "Para mostrar que entendí y sentí la historia", "Actuar muestra la comprensión."),
         ex("¿Qué ayuda a que se entienda cómo se siente el personaje?", "Los gestos y la voz", "Muestran la emoción."),
         ex("Si olvido una frase, ¿qué hago?", "Miro el texto y sigo", "No hay que parar.")],
        [ex("Escena: Ben has a new dog. He is happy. ¿Qué gesto haces como Ben?", "Sonrío y levanto los brazos", "Happy es contento."),
         ex("Escena: Lia says Hello! to a friend. ¿Con qué gesto acompañas la palabra Hello?", "Con la mano saludando", "Hello es hola y se saluda con la mano."),
         ex("Escena: The cat is sad. ¿Qué voz usas: alegre o baja?", "Baja", "Sad es triste.")],
        [ex("Pedro leyó muy rápido y con voz de enojo en la escena de un niño contento. ¿Qué cambiaría?", "Hablar despacio y con voz alegre", "La voz debe mostrar contento."),
         ex("Si no hay marionetas, ¿puedo dramatizar con un peluche?", "Sí", "Los objetos de casa sirven para actuar.")],
        [ex("Escena de dos personajes. Mia: Hello, Tom! Tom: Hello, Mia! I am happy. Escribe quién dice I am happy.", "Tom", "La línea de Tom lo dice."),
         ex("Escena: Sam: I have a ball. Pia: Me too! ¿Qué gesto harías para decir Me too?", "Levantar la mano y sonreír", "Me too es yo también y se muestra contento.")],
    ),
    context=[ex("En casa, tu hermano lee: A girl loses her hat. She is sad. Luego encuentra el sombrero: She is happy! ¿Qué cara haces primero y después?", "Triste y luego contenta", "Sad va primero y happy después.")],
    selfcheck=[ex("¿Qué significa sad?", "Triste", "Sad es triste."),
               ex("¿Cómo muestras que estás happy?", "Sonriendo", "Es el gesto de contento."),
               ex("¿Hay que actuar perfecto?", "No", "Lo importante es participar.")],
    open_task=task("Con un adulto, actúa esta escena. Mia: Hello, Tom! Tom: Hello, Mia! Mia: I am happy. Tom: Me too! Cada uno dice sus frases con gestos. Luego dibuja la cara de tu personaje.",
                   "Yo fui Mia. Dije Hello, Tom! saludando con la mano y I am happy sonriendo. Dibujé una cara sonriente.",
                   ["dice sus frases", "usa gestos", "muestra la emoción"], ["actuación frente a un adulto", "dibujo de la cara"], ["hablar muy bajo", "no mirar a su compañero"],
                   "Pide que repita una frase con un gesto más claro. Celebra cada intento."),
    reinforce="Actúa con un peluche una escena de Hello e I am happy.",
    extend="Inventa con un adulto una escena de tres líneas en inglés y actúenla.",
)

